repo.bookings.py:
"""Booking records."""


class Booking:
    def __init__(self, hotel, nights):
        self.hotel = hotel
        self.nights = nights

    def __repr__(self):
        return "Booking(%r, %r)" % (self.hotel, self.nights)


ROWS = [('harbour', 52), ('grand', 30), ('plaza', 10), ('plaza', 37), ('grand', 54), ('lodge', 8)]


def load_bookings():
    """Yield the stored bookings one at a time."""
    for hotel, nights in ROWS:
        yield Booking(hotel, nights)

