"""Distinct hotel values among bookings."""


def new_hotels(bookings, seen=set()):
    """Return each hotel the first time it appears among the bookings, in order. hotel values already in `seen` are left out."""
    out = []
    for x in bookings:
        if x.hotel not in seen:
            seen.add(x.hotel)
            out.append(x.hotel)
    return out


def count_hotels(bookings):
    """Return how many distinct hotel values the bookings have."""
    return len(set(x.hotel for x in bookings))


def largest_nights(bookings):
    """Return the largest nights, or None when there are no bookings."""
    values = [x.nights for x in bookings]
    return max(values) if values else None
